using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NationalPersonnelTests
{
    static ContractWorld New()=>AssessmentNotice.Create();
    static EntityId LordWork=>new("work:lord-inspect");
    static EntityId ClerkWork=>new("work:clerk-inspect");
    [Fact] public void CoverageIsCompleteWithoutInventingLords(){var coverage=NationalPersonnel.Coverage();Assert.Equal(108,coverage.Length);Assert.Equal(108,coverage.Select(c=>c.Node).Distinct().Count());Assert.Equal(105,coverage.Count(c=>c.People==0));Assert.Equal(new[]{"castle","kofu","odawara"},coverage.Where(c=>c.People>0).Select(c=>c.Node).Order().ToArray());Assert.Equal(3,NationalPersonnel.Catalog.Factions.Length);NationalPersonnel.ValidateCatalog(NationalPersonnel.Catalog);}
    [Fact] public void CatalogCannotMutateTheSourceOrWorld(){var w=New();string hash=ContractJson.CanonicalHash(w);string version=NationalPersonnel.Version;var c=NationalPersonnel.Catalog;c.People[0]=c.People[0] with{Name="tampered"};c.Sources[0]=c.Sources[0] with{Fact="tampered"};_ =NationalPersonnel.Coverage();Assert.Equal(version,ContractJson.CanonicalHash(NationalPersonnel.Catalog));Assert.Equal(hash,ContractJson.CanonicalHash(w));Assert.NotEqual("tampered",NationalPersonnel.Catalog.People[0].Name);}
    [Theory][InlineData("source")][InlineData("home")][InlineData("identity")][InlineData("duplicate")][InlineData("work")][InlineData("date")]
    public void BrokenProvenanceOrHistoricalAuthorityCannotPass(string kind){var c=NationalPersonnel.Catalog;if(kind=="source")c.People[0]=c.People[0] with{SourceIds=["missing"]};if(kind=="home")c.People[0]=c.People[0] with{HomeCandidate="shuri"};if(kind=="identity")c.People[0]=c.People[0] with{Id=ContractFixture.Lord};if(kind=="duplicate")c.Factions[1]=c.Factions[0];if(kind=="work")c.Work[0]=c.Work[0] with{Issuer=new("person:nobunaga")};if(kind=="date")c.Sources[0]=c.Sources[0] with{CheckedOn="invalid"};Assert.Throws<InvalidDataException>(()=>NationalPersonnel.ValidateCatalog(c));}
    [Fact] public void HistoricalSeedNeverBecomesAnAuthorizedDispatcher(){var w=New();foreach(var p in NationalPersonnel.Catalog.People){Assert.Empty(NationalPersonnel.DispatcherOptions(w,p.Id));Assert.DoesNotContain(w.Grants,g=>g.Agent==p.Id);Assert.DoesNotContain(w.ServiceBonds,b=>b.Target==p.Id||b.Subject==p.Id);}Assert.Throws<InvalidDataException>(()=>NationalPersonnel.Build(w,new("work:unknown"),"request:bad"));}
    [Theory][InlineData(false)][InlineData(true)] public void TemplatesUseExistingPhysicalContractWithoutPrematureKnowledge(bool subordinate){var s=new WorldSession(New());var w=s.DiagnosticSnapshot();var work=subordinate?ClerkWork:LordWork;var i=NationalPersonnel.Build(w,work,"request:catalog");Assert.Equal(IncomingMission.Build(w,"request:catalog",subordinate),i);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);Assert.Empty(IncomingMission.View(s,ContractFixture.Officer));Assert.False(NationalPersonnel.DispatcherOptions(s.DiagnosticSnapshot(),i.Actor).Single().CanDispatch);s.AdvanceTo(1);Assert.Null(IncomingMission.View(s,ContractFixture.Officer).Single().Task);var message=IncomingMission.View(s,ContractFixture.Officer).Single().Message;Assert.Equal(ResultCode.Accepted,s.Open(ContractFixture.Officer,message,s.Revision).Code);if(subordinate)Assert.Equal(ResultCode.Accepted,s.Assent(s.DiagnosticSnapshot().Tasks.Single().Id,ContractFixture.Officer,true,s.Revision).Code);s.SetPaused(false);s.AdvanceTo(12);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Theory][InlineData("service")][InlineData("grant")][InlineData("recipient-grant")][InlineData("expired")][InlineData("not-yet")][InlineData("away")][InlineData("field")][InlineData("dead")]
    public void DispatchRechecksActualRelationsLocationAndAuthority(string kind){var w=New();if(kind=="service")w.ServiceBonds=[];if(kind=="grant")w.Grants=w.Grants.Where(g=>g.Agent!=ContractFixture.Lord).ToArray();if(kind=="recipient-grant")w.Grants=w.Grants.Where(g=>g.Agent!=ContractFixture.Officer).ToArray();if(kind=="expired")w.ServiceBonds=w.ServiceBonds.Select(b=>b with{Until=0}).ToArray();if(kind=="not-yet")w.ServiceBonds=w.ServiceBonds.Select(b=>b with{From=1}).ToArray();if(kind=="away")w.Locations=w.Locations.Select(l=>l.Actor==ContractFixture.Lord?l with{Site=new("site:kofu")}:l).ToArray();if(kind=="field")w.Region=w.Region! with{Active=true};if(kind=="dead")w.Characters=w.Characters.Select(c=>c.Id==ContractFixture.Lord?c with{Life=LifeState.Dead}:c).ToArray();Assert.False(NationalPersonnel.DispatcherOptions(w,ContractFixture.Lord).Single().CanDispatch);Assert.Equal("現在は発送できません",NationalPersonnel.DispatcherOptions(w,ContractFixture.Lord).Single().Reason);Assert.Throws<InvalidDataException>(()=>NationalPersonnel.Build(w,LordWork,"request:recheck"));}
    [Fact] public void UnrelatedHiddenFactsDoNotChangeAvailabilityOrReasons(){var a=New();var b=ContractJson.Copy(a);b.Characters=b.Characters.Select(c=>c.Id==ContractFixture.Officer?c with{WillObey=false}:c).ToArray();b.Characters=b.Characters.Select(c=>c.Id==new EntityId("person:shingen")?c with{WillObey=false}:c).ToArray();b.Locations=b.Locations.Select(l=>l.Actor==new EntityId("person:shingen")?l with{Site=new("site:shuri")}:l).ToArray();Assert.Equal(ContractJson.Write(NationalPersonnel.DispatcherOptions(a,ContractFixture.Lord)),ContractJson.Write(NationalPersonnel.DispatcherOptions(b,ContractFixture.Lord)));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(5)] public void ExistingSaveSchemaRestoresDispatchedWorkAndContinuation(long at){var s=new WorldSession(New());s.Submit(NationalPersonnel.Build(s.DiagnosticSnapshot(),LordWork,"request:save"),s.Revision);if(at>0)s.AdvanceTo(1);if(at>=1){s.Open(ContractFixture.Officer,IncomingMission.View(s,ContractFixture.Officer).Single().Message,s.Revision);s.SetPaused(false);s.AdvanceTo(at);}var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"personnel-"+Guid.NewGuid().ToString("N")),New().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.25,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetActorView(ContractFixture.Officer) with{Revision=0}),ContractJson.Write(host.Current.GetActorView(ContractFixture.Officer) with{Revision=0}));foreach(var session in new[]{s,host.Current}){session.SetPaused(false);if(at==0){session.AdvanceTo(1);session.Open(ContractFixture.Officer,IncomingMission.View(session,ContractFixture.Officer).Single().Message,session.Revision);session.SetPaused(false);}session.AdvanceTo(12);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Tasks.Select(t=>t with{Revision=0}).ToArray()),ContractJson.Write(host.Current.DiagnosticSnapshot().Tasks.Select(t=>t with{Revision=0}).ToArray()));Assert.Equal(ContractJson.Write(s.GetActorView(ContractFixture.Officer) with{Revision=0}),ContractJson.Write(host.Current.GetActorView(ContractFixture.Officer) with{Revision=0}));}
}
